-- 014_optional_esp32_iot_course.sql
insert into public.courses(title,slug,description,equipment)
values('ESP32 и IoT — полный курс','esp32-iot','Дополнительный безопасный курс: ESP32, Arduino IDE, GPIO, датчики, Wi‑Fi, локальный веб, MQTT-концепции, данные и IoT-проекты.','ESP32 + безопасные низковольтные учебные модули')
on conflict(slug) do update set title=excluded.title,description=excluded.description,equipment=excluded.equipment,active=true;
with c as(select id from public.courses where slug='esp32-iot')
insert into public.lessons(course_id,title,description,lesson_order,duration_minutes)
select c.id,v.t,v.d,v.o,v.m from c cross join(values ('Что такое ESP32','Микроконтроллер для IoT',1,30),('ESP32 и Arduino','Сходства и различия',2,30),('GPIO','Цифровые контакты',3,30),('Wi‑Fi и Bluetooth','Беспроводные возможности',4,30),('Arduino IDE','Среда разработки',5,30),('Поддержка ESP32 в Arduino IDE','Пакет плат',6,30),('Выбор платы и порта','Подключение',7,30),('Первый скетч','Компиляция и загрузка',8,30),('setup() и loop()','Структура Arduino-скетча',9,30),('Serial Monitor','Текстовая диагностика',10,30),('Переменные','Данные программы',11,30),('Условия','if / else',12,30),('Циклы','for',13,30),('Цифровой выход','Безопасный учебный LED',14,30),('Цифровой вход','Кнопка',15,30),('Debounce на уровне понятия','Стабильное нажатие',16,30),('PWM','Управление уровнем сигнала',17,30),('ADC','Чтение аналогового значения',18,30),('Калибровка на уровне проекта','Сырые и понятные данные',19,30),('Фильтрация измерений','Среднее нескольких чтений',20,30),('Температура/влажность','Учебный сенсор',21,30),('Освещённость','Свет как данные',22,30),('Пороговое событие','Датчик + условие',23,30),('Что такое Wi‑Fi в IoT','Устройство в сети',24,30),('Подключение к разрешённой сети','SSID и пароль',25,30),('IP-адрес','Адрес устройства',26,30),('Локальная веб-страница','ESP32 как учебный сервер',27,30),('Показание датчика на странице','IoT-интерфейс',28,30),('Что такое IoT','Датчик → сеть → данные',29,30),('MQTT на уровне понятия','Publish / Subscribe',30,30),('Топики MQTT','Структура сообщений',31,30),('Локальная демонстрация MQTT','Сообщения в контролируемой сети',32,30),('JSON на уровне понятия','Структурированные данные',33,30),('Пакет измерений','Несколько полей',34,30),('Serial Plotter','График измерений',35,30),('Переподключение Wi‑Fi','Состояние соединения',36,30),('Не хранить секреты в публичном коде','Пароли и токены',37,30),('Проверка данных','Допустимые диапазоны',38,30),('Debugging через Serial','Диагностика',39,30),('Проект «Мини-метеостанция»','Датчик + Serial',40,30),('Проект «Индикатор света»','Датчик + LED',41,30),('Проект «Локальный монитор»','Wi‑Fi + веб',42,30),('Проект «Беспроводной датчик»','Данные + контролируемая сеть',43,30),('План STEM-урока ESP32','Цель и критерий',44,30),('Чек-лист оборудования','Перед уроком',45,30),('Безопасность IoT-урока','Сеть и данные',46,30),('Собственный ESP32-проект','Идея → датчик → код → результат',47,30),('Документация проекта','Схема и описание',48,30),('Итоговая демонстрация','Полный цикл ESP32',49,30))v(t,d,o,m)
on conflict(course_id,lesson_order) do update set title=excluded.title,description=excluded.description,duration_minutes=excluded.duration_minutes,active=true;
insert into public.optional_course_catalog(course_id,sort_order,active)
select id,40,true from public.courses where slug='esp32-iot'
on conflict(course_id) do update set sort_order=excluded.sort_order,active=true;
